export function AdminCapabilitiesPage(): ReactElement { const q = useAdminQuery<AdminPermission[]>('capabilities', adminService.capabilities); return <Frame eyebrow="System Console" title="Capabilities" subtitle="Permission capabilities available in the standalone deployment." action={<Badge variant="warning"><Lock className="mr-1 h-3 w-3" />Catalog view</Badge>}><State loading={q.isLoading} error={q.error}>{q.data && <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3">{q.data.map((row) => <article key={row.id} className="rounded-lg border border-slate-200 bg-white p-4"><p className="text-sm font-semibold text-slate-900">{row.resource}</p><p className="mt-1 text-xs text-slate-500">{row.action}</p><p className="mt-3 font-mono text-[11px] text-brand-accent">{row.key}</p></article>)}</div>}</State></Frame>; }
export function AdminSettingsPage(): ReactElement {
  const q = useAdminQuery<AdminSettings>('settings', adminService.settings);
  const metrics = q.data ? [{ label: 'Organizations', value: q.data.organizations, icon: Building2, tone: 'bg-brand-accent/10 text-brand-accent' }, { label: 'Users', value: q.data.users, icon: Users, tone: 'bg-signal-tint text-signal-strong' }, { label: 'Whistleblowing cases', value: q.data.cases, icon: Activity, tone: 'bg-courage-tint text-courage-strong' }] : [];
  return <Frame eyebrow="System Console" title="Settings" subtitle="Platform configuration, environment health, and live deployment information." action={<Badge variant="warning"><Lock className="mr-1 h-3 w-3" />Read-only</Badge>}>
    <State loading={q.isLoading} error={q.error}>{q.data && <>
      <section className="relative overflow-hidden rounded-2xl border border-brand-primary/20 bg-brand-primary p-6 text-white shadow-protected sm:p-8"><div className="pointer-events-none absolute -right-16 -top-20 h-56 w-56 rounded-full bg-brand-accent/30 blur-3xl" aria-hidden="true" /><div className="relative flex flex-col gap-6 sm:flex-row sm:items-center sm:justify-between"><div><div className="flex items-center gap-2 text-[10px] font-semibold uppercase tracking-[0.16em] text-porcelain/70"><span className="h-2 w-2 rounded-full bg-moss" />System control plane</div><h2 className="mt-3 text-2xl font-semibold tracking-tight sm:text-3xl">Everything is running as expected.</h2><p className="mt-2 max-w-xl text-sm leading-6 text-porcelain/75">Review your deployment context and platform footprint from a single, read-only operations view.</p></div><div className="flex shrink-0 items-center gap-3 rounded-xl border border-white/15 bg-white/10 px-4 py-3"><span className="flex h-9 w-9 items-center justify-center rounded-full bg-moss/20 text-moss"><CircleCheck className="h-5 w-5" /></span><div><p className="text-xs font-semibold">Operational</p><p className="mt-0.5 text-[11px] text-porcelain/70">Live environment</p></div></div></div></section>
      <div className="grid gap-3 sm:grid-cols-3">{metrics.map(({ label, value, icon: Icon, tone }) => <article key={label} className="rounded-2xl border border-border bg-card p-5 shadow-sm"><div className="flex items-center justify-between gap-3"><div><p className="text-[10px] font-semibold uppercase tracking-[0.12em] text-muted-foreground">{label}</p><p className="mt-2 text-2xl font-semibold tracking-tight text-foreground">{value}</p></div><span className={`flex h-10 w-10 items-center justify-center rounded-xl ${tone}`}><Icon className="h-5 w-5" /></span></div><p className="mt-3 text-xs text-muted-foreground">Current live total</p></article>)}</div>
      <div className="grid gap-4 xl:grid-cols-[1.1fr_0.9fr]"><section className="rounded-2xl border border-border bg-card p-6 shadow-sm"><div className="flex items-start gap-3"><span className="flex h-10 w-10 items-center justify-center rounded-xl bg-brand-accent/10 text-brand-accent"><Gauge className="h-5 w-5" /></span><div><h2 className="text-base font-semibold text-foreground">Deployment information</h2><p className="mt-1 text-xs text-muted-foreground">The context this console is connected to.</p></div></div><dl className="mt-6 divide-y divide-border">{[['Product', q.data.product], ['Environment', q.data.apiEnvironment], ['Access model', 'Platform-wide'], ['Data mode', 'Read-only catalog']].map(([label, value]) => <div key={label} className="flex flex-wrap items-center justify-between gap-4 py-4 text-sm"><dt className="text-muted-foreground">{label}</dt><dd className="font-medium text-foreground">{value}</dd></div>)}</dl></section><section className="rounded-2xl border border-border bg-card p-6 shadow-sm"><div className="flex items-start gap-3"><span className="flex h-10 w-10 items-center justify-center rounded-xl bg-moss/10 text-moss"><ShieldCheck className="h-5 w-5" /></span><div><h2 className="text-base font-semibold text-foreground">Security posture</h2><p className="mt-1 text-xs text-muted-foreground">Controls currently active for this console.</p></div></div><div className="mt-6 space-y-3">{['Admin authentication required', 'Permission-gated platform routes', 'Read-only catalog resources'].map((item) => <div key={item} className="flex items-center gap-3 rounded-xl border border-border bg-muted/30 px-3 py-3 text-sm text-foreground"><CircleCheck className="h-4 w-4 shrink-0 text-moss" />{item}</div>)}</div><p className="mt-5 text-xs leading-5 text-muted-foreground">Changes to billing and shared catalog configuration are managed by platform operations.</p></section></div>
    </>}</State>
  </Frame>;
}
